cd /tmp/vally-eval-trial-SSsbsC && P=.copilot-tracking/skraft-plans/pricing && mkdir -p $P/features $P/details/2026-11-25 tests/CheckoutPricing.UnitTest/LoyaltyDiscount
cat > $P/features/pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: Bronze, Silver, Gold (AC-1..AC-4), every scenario below.
  # NOT DECIDED: Platinum tier. The business has not agreed a reduction, so no
  # scenario exists and no value may be invented. Escalated to DISCUSS; add
  # scenarios only once an expected value is agreed.

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer reduction lands on a whole cent in the customer's favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/LoyaltyDiscount/CalculateLoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.LoyaltyDiscount;

public class CalculateLoyaltyDiscountAcceptanceTests
{
    private static int ChargedFor(LoyaltyTier tier, int subtotalCents) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    // Bronze customer is charged the Bronze price
    [Fact]
    public void S1_BronzeBasketOf10000CentsIsCharged9500Cents() =>
        Assert.Equal(9500, ChargedFor(LoyaltyTier.Bronze, 10000));

    // Silver customer is charged the Silver price
    [Fact]
    public void S2_SilverBasketOf10000CentsIsCharged9000Cents() =>
        Assert.Equal(9000, ChargedFor(LoyaltyTier.Silver, 10000));

    // Gold customer is charged the Gold price
    [Fact]
    public void S3_GoldBasketOf10000CentsIsCharged8500Cents() =>
        Assert.Equal(8500, ChargedFor(LoyaltyTier.Gold, 10000));

    // Bronze customer reduction lands on a whole cent in the customer's favour
    [Fact]
    public void S4_BronzeBasketOf7CentsIsCharged7Cents() =>
        Assert.Equal(7, ChargedFor(LoyaltyTier.Bronze, 7));
}
EOF
dotnet test tests/CheckoutPricing.UnitTest 2>&1 | grep -E "error|Failed|Passed!|Failed!|Assert|Expected|Actual" | head -30

